"use client";
import {use} from "react"; import Link from "next/link"; import {useQuery} from "@tanstack/react-query"; import {vendorApi} from "@/apis/admin/vendorApi"; import {ArrowLeft,Building2,Phone,Mail,MapPin} from "lucide-react";
const border={borderColor:"var(--border-color)"};function Status({value}){return <span className="rounded px-2 py-1 text-[11px] font-semibold" style={{backgroundColor:value?"var(--success-soft)":"var(--bg-tertiary)",color:value?"var(--success-text)":"var(--text-muted)"}}>{value?"Active":"Inactive"}</span>}
export default function VendorDetailPage({params}){const{id}=use(params);const{data,isLoading,isError,refetch}=useQuery({queryKey:["vendor",id],queryFn:()=>vendorApi.getWithPOs(id)});if(isLoading)return <div className="space-y-3"><div className="skeleton h-7 w-1/3"/><div className="skeleton h-32 w-full"/><div className="skeleton h-40 w-full"/></div>;if(isError||!data)return <div className="rounded-lg border p-8 text-center" style={border}><p className="text-sm">Vendor details could not be loaded.</p><button onClick={()=>refetch()} className="mt-2 text-sm" style={{color:"var(--accent)"}}>Try again</button><div><Link href="/admin/vendors" className="mt-3 inline-block text-sm underline">Back to vendors</Link></div></div>;const money=x=>`Rs. ${Number(x||0).toLocaleString()}`;return <div className="space-y-4" style={{color:"var(--text-primary)"}}><Link href="/admin/vendors" className="inline-flex items-center gap-1 text-sm" style={{color:"var(--text-secondary)"}}><ArrowLeft className="h-4 w-4"/>Vendors</Link><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-semibold uppercase tracking-wider" style={{color:"var(--text-muted)"}}>Vendor details</p><div className="mt-1 flex flex-wrap items-center gap-2"><h1 className="text-xl font-bold">{data.name}</h1><Status value={data.is_active}/></div><p className="mt-1 font-mono text-sm" style={{color:"var(--text-muted)"}}>{data.vendor_code}{data.company_name?` · ${data.company_name}`:""}</p></div></div>
<div className="grid gap-3 sm:grid-cols-3"><div className="rounded-lg border p-4" style={{...border,backgroundColor:"var(--bg-card)"}}><p className="text-xs" style={{color:"var(--text-muted)"}}>Total purchases</p><p className="mt-1 text-lg font-bold tabular-nums">{money(data.total_purchased)}</p></div><div className="rounded-lg border p-4" style={{...border,backgroundColor:"var(--bg-card)"}}><p className="text-xs" style={{color:"var(--text-muted)"}}>Paid</p><p className="mt-1 text-lg font-bold tabular-nums">{money(data.total_paid)}</p></div><div className="rounded-lg border p-4" style={{...border,backgroundColor:"var(--bg-card)"}}><p className="text-xs" style={{color:"var(--text-muted)"}}>Outstanding</p><p className="mt-1 text-lg font-bold tabular-nums">{money(data.balance_payable)}</p></div></div>
<section className="rounded-lg border p-4" style={{...border,backgroundColor:"var(--bg-card)"}}><h2 className="text-sm font-semibold">Overview</h2><div className="mt-3 grid gap-x-6 gap-y-4 text-sm sm:grid-cols-2 lg:grid-cols-3"><div className="flex gap-2"><Building2 className="mt-0.5 h-4 w-4 shrink-0" style={{color:"var(--text-muted)"}}/><div><p className="text-xs" style={{color:"var(--text-muted)"}}>Contact person</p>{data.contact_person||"—"}</div></div><div className="flex gap-2"><Phone className="mt-0.5 h-4 w-4 shrink-0" style={{color:"var(--text-muted)"}}/><div><p className="text-xs" style={{color:"var(--text-muted)"}}>Phone</p>{data.phone||"—"}{data.whatsapp&&<div className="text-xs">WhatsApp {data.whatsapp}</div>}</div></div><div className="flex gap-2"><Mail className="mt-0.5 h-4 w-4 shrink-0" style={{color:"var(--text-muted)"}}/><div><p className="text-xs" style={{color:"var(--text-muted)"}}>Email</p>{data.email||"—"}</div></div><div className="flex gap-2"><MapPin className="mt-0.5 h-4 w-4 shrink-0" style={{color:"var(--text-muted)"}}/><div><p className="text-xs" style={{color:"var(--text-muted)"}}>Location</p>{[data.city,data.state,data.country].filter(Boolean).join(", ")||"—"}</div></div><div><p className="text-xs" style={{color:"var(--text-muted)"}}>Payment terms</p>{String(data.payment_terms||"—").replaceAll("_"," ")}</div><div><p className="text-xs" style={{color:"var(--text-muted)"}}>Lead time</p>{data.lead_time_days??0} days</div></div></section>
<section className="overflow-hidden rounded-lg border" style={{...border,backgroundColor:"var(--bg-card)"}}><div className="border-b px-4 py-3" style={border}><h2 className="text-sm font-semibold">Purchase orders <span style={{color:"var(--text-muted)"}}>({data.purchaseOrders?.length||0})</span></h2></div><div className="overflow-x-auto"><table className="w-full min-w-[520px] text-left text-[13px]"><thead style={{backgroundColor:"var(--bg-tertiary)",color:"var(--text-secondary)"}}><tr>{["PO number","Status","Total","Paid"].map(h=><th key={h} className="px-4 py-2.5 font-semibold">{h}</th>)}</tr></thead><tbody>{(data.purchaseOrders||[]).map(p=><tr key={p._id} className="border-t" style={border}><td className="px-4 py-3"><Link href={`/admin/purchase-orders/${p._id}`} className="font-mono font-semibold hover:underline">{p.po_number}</Link></td><td className="px-4 py-3 capitalize">{String(p.status||"—").replaceAll("_"," ")} <span className="text-xs" style={{color:"var(--text-muted)"}}>· {String(p.payment_status||"—").replaceAll("_"," ")}</span></td><td className="px-4 py-3">{money(p.total)}</td><td className="px-4 py-3">{money(p.paid_amount)}</td></tr>)}{!data.purchaseOrders?.length&&<tr><td colSpan={4} className="px-4 py-8 text-center text-sm" style={{color:"var(--text-muted)"}}>No purchase orders for this vendor.</td></tr>}</tbody></table></div></section>
<section className="overflow-hidden rounded-lg border" style={{...border,backgroundColor:"var(--bg-card)"}}><div className="border-b px-4 py-3" style={border}><h2 className="text-sm font-semibold">Products <span style={{color:"var(--text-muted)"}}>({data.products?.length||0})</span></h2></div><div className="divide-y" style={border}>{(data.products||[]).map(p=><div key={String(p.product_id)} className="flex flex-wrap items-center justify-between gap-2 px-4 py-3 text-sm" style={border}><span className="font-medium">{p.name}</span><span className="font-mono text-xs" style={{color:"var(--text-muted)"}}>{p.sku}</span></div>)}{!data.products?.length&&<p className="px-4 py-8 text-center text-sm" style={{color:"var(--text-muted)"}}>No products listed.</p>}</div></section></div>}
